/**
 * The seed catalog is intentionally represented as explicit data rather than
 * being derived from a range or generated at runtime. This keeps the fixture
 * easy to inspect, stable when imported by tests, and useful as a small source
 * of realistic project records during development. Every record follows the
 * same contract: a zero-padded project identifier, the matching display title,
 * and the published lifecycle state. The complete catalog is kept in numeric
 * order so that reviewing, diffing, and selecting a known seed remain simple.
 *
 * Keep entries in this file literal. In particular, avoid replacing the list
 * with Array.from, a loop, or a helper that synthesizes records: the explicit
 * catalog is part of the fixture's purpose and makes its contents searchable.
 */
export type ProjectSeed = {
  id: string;
  title: string;
  status: "published";
};

export const PROJECT_SEEDS: ProjectSeed[] = [
  // Entries 001-010
  {
    id: "project-001",
    title: "Project 001",
    status: "published",
  },
  {
    id: "project-002",
    title: "Project 002",
    status: "published",
