export function normalizeStorageKey(value: string): string | null {
  let decoded: string;

  try {
    decoded = decodeURIComponent(value);
  } catch {
    return null;
  }

  const normalized = decoded.replaceAll("\\", "/");

  if (normalized.startsWith("/") || /^[A-Za-z]:\//.test(normalized)) {
    return null;
  }

  const segments = normalized.split("/");
  const result: string[] = [];

  for (const segment of segments) {
    if (!segment || segment === ".") {
      continue;
    }

    let encodedSegment = segment;
    while (true) {
      if (encodedSegment.replaceAll("\\", "/").split("/").includes("..")) {
        return null;
      }

      if (!encodedSegment.includes("%")) {
        break;
      }

      try {
        const nextSegment = decodeURIComponent(encodedSegment);
        if (nextSegment === encodedSegment) {
          break;
        }
        encodedSegment = nextSegment;
      } catch {
        break;
      }
    }

    result.push(segment);
  }

  return result.length > 0 ? result.join("/") : null;
}

export function normalizeStorageKey(value: string): string | null {
  let decoded: string;

  try {
    decoded = decodeURIComponent(value);
  } catch {
    return null;
  }

  const normalized = decoded.replaceAll("\\", "/");
  let validationPath = normalized;

  while (validationPath.includes("%")) {
    let nextPath: string;

    try {
      nextPath = decodeURIComponent(validationPath);
    } catch {
      break;
    }

    if (nextPath === validationPath) {
      break;
    }

    validationPath = nextPath.replaceAll("\\", "/");
  }

  if (
    validationPath.startsWith("/") ||
    /^[A-Za-z]:\//.test(validationPath) ||
    validationPath.split("/").some((segment) => segment === "..")
  ) {
    return null;
  }

  const result = normalized
    .split("/")
    .filter((segment) => segment && segment !== ".");

  return result.length > 0 ? result.join("/") : null;
}

