const fields: string[] = [];
let value = "";
let inQuotes = false;
let quoted = false;
let afterClosingQuote = false;

const addField = () => {
  fields.push(quoted ? value : value.trim());
  value = "";
  inQuotes = false;
  quoted = false;
  afterClosingQuote = false;
};

for (let index = 0; index < row.length; index += 1) {
  const character = row[index];

  if (inQuotes) {
    if (character === '"') {
      if (row[index + 1] === '"') {
        value += '"';
        index += 1;
      } else {
        inQuotes = false;
        afterClosingQuote = true;
      }
    } else {
      value += character;
    }
  } else if (character === ",") {
    addField();
  } else if (character === '"' && value.trim() === "" && !quoted) {
    value = "";
    inQuotes = true;
    quoted = true;
  } else if (!afterClosingQuote) {
    value += character;
  }
}

addField();
return fields;

