export function parseCsvRow(row: string): string[] {
  const values: string[] = [];
  let field = "";
  let inQuotes = false;
  let quotedField = false;

  for (let index = 0; index < row.length; index += 1) {
    const character = row[index];

    if (inQuotes) {
      if (character === '"') {
        if (row[index + 1] === '"') {
          field += '"';
          index += 1;
        } else {
          inQuotes = false;
          quotedField = true;
        }
      } else {
        field += character;
      }
    } else if (character === ",") {
      values.push(quotedField ? field : field.trim());
      field = "";
      quotedField = false;
    } else if (character === '"' && field.length === 0) {
      inQuotes = true;
    } else {
      field += character;
    }
  }

  values.push(quotedField ? field : field.trim());
  return values;
}

