export function normalizeStorageKey(value: string): string | null {
  if (typeof value !== "string" || value.length === 0) {
    return null;
  }

  let decoded: string;
  try {
    decoded = decodeURIComponent(value);

    // Decode nested URI escapes as well, so encoded traversal cannot survive
    // one decoding pass and become a path separator or `..` segment later.
    while (/%[0-9a-fA-F]{2}/.test(decoded)) {
      const next = decodeURIComponent(decoded);
      if (next === decoded) {
        break;
      }
      decoded = next;
    }
  } catch {
    return null;
  }

  const path = decoded.replaceAll("\\", "/");
  if (path.startsWith("/") || /^[A-Za-z]:\//.test(path)) {
    return null;
  }

  const segments = path.split("/");
  if (segments.some((segment) => segment === "..")) {
    return null;
  }

  const normalized = segments
    .filter((segment) => segment && segment !== ".")
    .join("/");

  return normalized || null;
}

