operations.content:
export type ProjectRecord = {
  id: string;
  title: string;
  slug: string;
  published: boolean;
  createdAt: Date;
};

export function serializeProject(project: ProjectRecord) {
  return {
    id: project.id,
    title: normalizeProjectTitle(project.title),
    slug: project.slug,
    published: project.published,
    createdAt: project.createdAt.toISOString(),
  };
}

